{"createSurface":{"surfaceId":"feedback","catalogId":"https://ui.exponential.at/catalogs/core/v1"}}
{"updateComponents":{"surfaceId":"feedback","components":[{"id":"root","component":"Box","style":{"display":"flex","justifyContent":"center","padding":"$spacing.lg"},"children":["card","toast"]},{"id":"card","component":"Card","title":"Send feedback","description":"Tell us what's working and what isn't. We read every message.","style":{"width":"100%","maxWidth":560},"children":["form"]},{"id":"form","component":"Form","name":"feedback","on":{"submit":{"event":{"name":"feedback.submit","context":{"rating":{"path":"/feedback/rating"},"category":{"path":"/feedback/category"},"message":{"path":"/feedback/message"},"files":{"path":"/feedback/files"}}},"functionCall":{"call":"set","args":{"path":"/toast/open","value":true}}}},"children":["ratingBlock","category","message","upload","actions"]},{"id":"ratingBlock","component":"Stack","gap":"xs","children":["ratingLabel","ratingRow"]},{"id":"ratingLabel","component":"Label","text":"How would you rate your experience?","required":true},{"id":"ratingRow","component":"Stack","direction":"horizontal","gap":"sm","align":"center","children":["rating","ratingText"]},{"id":"rating","component":"Rating","max":5,"size":"lg","value":{"path":"/feedback/rating"}},{"id":"ratingText","component":"Text","variant":"muted","text":{"call":"map","args":{"value":{"path":"/feedback/rating"},"cases":{"1":"Poor","2":"Fair","3":"Good","4":"Great","5":"Excellent"},"default":"Not rated yet"}}},{"id":"category","component":"Radio","label":"Category","name":"category","orientation":"horizontal","value":{"path":"/feedback/category"},"options":[{"label":"Bug","value":"bug","icon":"bug"},{"label":"Idea","value":"idea","icon":"lightbulb"},{"label":"Praise","value":"praise","icon":"heart"}],"checks":[{"condition":{"call":"required","args":{"value":{"path":"/feedback/category"}}},"message":"Pick a category."}]},{"id":"message","component":"Textarea","label":"Message","name":"message","placeholder":"What happened, or what would you like to see?","rows":5,"autosize":true,"maxRows":12,"value":{"path":"/feedback/message"},"checks":[{"condition":{"call":"required","args":{"value":{"path":"/feedback/message"}}},"message":"Please write a message."},{"condition":{"call":"length","args":{"value":{"path":"/feedback/message"},"min":10,"max":2000}},"message":"Use between 10 and 2000 characters."}]},{"id":"upload","component":"FileUpload","label":"Screenshot (optional)","name":"screenshot","accept":"image/*","maxSize":10485760,"hint":"PNG or JPG, up to 10 MB","files":{"path":"/feedback/files"},"on":{"upload":{"event":{"name":"feedback.upload"}},"remove":{"event":{"name":"feedback.removeFile"}}}},{"id":"actions","component":"Stack","direction":"horizontal","justify":"end","children":["submit"]},{"id":"submit","component":"Button","label":"Send feedback","icon":"send","submit":true,"disabled":{"call":"lt","args":{"a":{"call":"fallback","args":{"value":{"path":"/feedback/rating"},"default":0}},"b":1}}},{"id":"toast","component":"Toast","type":"success","title":"Thanks for your feedback!","description":"We've received your message and will look into it.","open":{"path":"/toast/open"},"duration":5000}]}}
